import { redirect } from "next/navigation";
import { requestPasswordReset, resetPassword } from "@/lib/users";

async function requestReset(formData: FormData) {
  "use server";
  await requestPasswordReset(String(formData.get("email") ?? ""));
  redirect("/reset-password?sent=1");
}

async function setNewPassword(formData: FormData) {
  "use server";
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < 8) redirect(`/reset-password?token=${encodeURIComponent(token)}&error=short`);
  const ok = await resetPassword(token, password);
  redirect(ok ? "/reset-password?done=1" : "/reset-password?error=invalid");
}

export default async function ResetPasswordPage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string; sent?: string; done?: string; error?: string }>;
}) {
  const { token, sent, done, error } = await searchParams;

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">Reset password</h1>

      {done ? (
        <p className="mt-4 text-sm">Your password has been updated.</p>
      ) : sent ? (
        <p className="mt-4 text-sm">If an account exists for that email, a reset link is on its way.</p>
      ) : token ? (
        <form action={setNewPassword} className="mt-4 space-y-3">
          <input type="hidden" name="token" value={token} />
          <input
            type="password"
            name="password"
            required
            minLength={8}
            placeholder="New password"
            className="w-full rounded border px-3 py-2"
          />
          {error === "short" && <p className="text-sm text-red-600">Use at least 8 characters.</p>}
          <button className="rounded bg-black px-4 py-2 text-white">Set new password</button>
        </form>
      ) : (
        <form action={requestReset} className="mt-4 space-y-3">
          {error === "invalid" && (
            <p className="text-sm text-red-600">That reset link is invalid or has expired. Request a new one.</p>
          )}
          <input
            type="email"
            name="email"
            required
            placeholder="you@example.com"
            className="w-full rounded border px-3 py-2"
          />
          <button className="rounded bg-black px-4 py-2 text-white">Send reset link</button>
        </form>
      )}
    </main>
  );
}
EOF
